    always @(posedge clk ) begin
        if (reset == 1'b1)
            empty_n <= 1'b0;
        else if (push & ~pop)
            empty_n <= 1'b1;
        else if (~push & pop)
            empty_n <= (mOutPtr != 1'b1);
    end

    // if_num_data_valid 
    always @(posedge clk ) begin
        if (reset == 1'b1)
            if_num_data_valid <= 'b0;
        else if (pop)
            if_num_data_valid <= mOutPtr + push;
        else if (~(if_read_ce & if_read) & dout_vld)
            if_num_data_valid <= mOutPtr + push + 1;
        else
            if_num_data_valid <= 'b0;
    end // 

    // dout_vld 
    always @(posedge clk ) begin
        if (reset == 1'b1)
            dout_vld <= 1'b0;
        else if (pop)
            dout_vld <= 1'b1;
        else if (if_read_ce & if_read)
            dout_vld <= 1'b0;
    end // 

endmodule


